package fable.hideseek.imba.net;
import fable.hideseek.imba.game.GameRoles;import fable.hideseek.imba.mask.MaskService;import fable.hideseek.imba.mask.MaskState;import io.netty.buffer.Unpooled;import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.networking.v1.ServerPlayNetworking;import net.minecraft.network.PacketByteBuf;import net.minecraft.text.Text;import net.minecraft.util.Identifier;
public final class WallClimbNetworking implements ModInitializer{public static final Identifier TOGGLE=new Identifier("imba","wall_climb_toggle_v2"),STATE=new Identifier("imba","wall_climb_state");@Override public void onInitialize(){ServerPlayNetworking.registerGlobalReceiver(TOGGLE,(server,player,handler,buf,responseSender)->server.execute(()->{if(!GameRoles.isHider(player)||!MaskState.hasMask(player.getUuid()))return;MaskState state=MaskState.get(player.getUuid());if(!MaskService.supportsWallClimbing(state)){player.sendMessage(Text.literal("§cЭта маскировка не умеет ползать по стенам"),true);return;}state.wallClimbing=!state.wallClimbing;PacketByteBuf b=new PacketByteBuf(Unpooled.buffer());b.writeBoolean(state.wallClimbing);ServerPlayNetworking.send(player,STATE,b);player.sendMessage(Text.literal(state.wallClimbing?"§aПолзание по стенам: ВКЛ":"§cПолзание по стенам: ВЫКЛ"),true);}));}}
